window.sleep = (ms) => new Promise((r) => setTimeout(r, ms));
window.until = async (fn, ms = 15000) => { const t0 = Date.now(); while (Date.now() - t0 < ms) { if (await fn()) return true; await sleep(250) } return false };
window.nav = async (name) => { const b = [...document.querySelectorAll('nav button')].find((x) => x.textContent.trim() === name); if (!b) return 'NO NAV ' + name; b.click(); await sleep(2000); return 'nav ' + name };
window.button = (name, within) => [...(within ?? document).querySelectorAll('button')].find((x) => x.textContent.trim() === name);
window.section = (name) => document.querySelector('section[aria-label="' + name + '"]');
window.dl = async (league) => (await window.api.leagues.downloads()).leagues.find((l) => l.league === league);
window.BOARD = { entity: 'player', metrics: ['pts', 'reb', 'ast', 'stl', 'blk', 'ts_pct'], scope: { seasons: [2026] } };
window.timeBoard = async () => { const t0 = performance.now(); const r = await window.api.stats.query('nba', BOARD); return { ms: Math.round(performance.now() - t0), rows: r.rows.length, top: r.rows[0]?.name } };
window.check = (label, ok, got) => (ok ? 'OK ' : 'MISMATCH ') + label + ' got ' + JSON.stringify(got);
window.trigger = () => document.querySelector('button[aria-label^="League: "]');
window.league = () => trigger()?.getAttribute('aria-label')?.replace('League: ', '') ?? null;
window.mainText = () => document.querySelector('main')?.innerText ?? '';
window.switchTo = async (name) => { const t = trigger(); if (!t) return 'NO MENU'; t.focus(); t.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true })); await until(() => document.querySelectorAll('[role=menuitemradio]').length > 0, 3000); const item = [...document.querySelectorAll('[role=menuitemradio]')].find((x) => x.textContent.startsWith(name)); if (!item) return 'NO ITEM ' + name; item.click(); await until(() => league() === name, 5000); await sleep(3000); return league() };
window.families = async (league) => (await window.api.stats.data(league)).families;
